#!/bin/bash
# Builds the camera pieces on the build PC:
#   camera_host: ICameraHost 1.2 as camera_service (the asteroids_camera_hdi service), in front of camserver
#     (platform/qcom/camera/bridge), with the flash as a torch while no camera is open (camera_host.cpp).
# The camera HDI 1.0-1.2 C++ headers are generated by hdi-gen from OpenHarmony's drivers_interface/camera, as for the
# vibrator and sensor services; the stub and proxies at run time are the donor's. The ability blob is made with the
# donor's camera metadata library (chipset-sdk/libmetadata.z.so) and OpenHarmony's headers for it.
# Output: $WORK/out-camera/.
set -e
. "$(dirname "$0")/../../../build/env.sh"
HB=${HARMONY_BUILD:-$HOME/harmony-build}
M2=$WORK
N=$HB/ohos/sdk/native
S=$HB/ohos/src
O=$WORK/out-camera
L=$WORK/out-sensors/link
G=$O/gen
H=$(cd "$(dirname "$0")" && pwd)
DONOR=$HB/donor/pura70proplus-7.0.0.107/mnt/system/system
mkdir -p $O/link
[ -f $L/libhdi.z.so ] || { echo "run sensors/build-sensors.sh first (donor link libraries)"; exit 1; }
[ -f $O/link/libmetadata.z.so ] || { sudo -n cp $DONOR/lib64/chipset-sdk/libmetadata.z.so $O/link/ &&
    sudo -n chown "$(id -u):$(id -g)" $O/link/libmetadata.z.so; }

HG=$S/drivers_hdf_core/framework/tools/hdi-gen/hdi-gen
I=$O/idl/ohos/hdi/camera
rm -rf $O/idl $G && mkdir -p $I $G
cp -r $S/drivers_interface/camera/v1_0 $S/drivers_interface/camera/v1_1 $S/drivers_interface/camera/v1_2 \
    $S/drivers_interface/camera/v1_3 $I/
# In one run, so the 1.1-1.3 interfaces find the ones they extend.
$HG -s full -m ipc -l cpp -r ohos.hdi:$O/idl/ohos/hdi $(for f in $I/v1_*/*.idl; do echo -c $f; done) -d $G

HDF=$S/drivers_hdf_core/interfaces/inner_api
CI=$S/drivers_interface/camera
INC="-I$G -I$G/camera -I$HDF/hdi -I$HDF/ipc -I$HDF/hdi/base -I$HDF/utils -I$HDF/osal/uhdf -I$HDF/core -I$HDF/host/uhdf
     -I$CI/metadata/include -I$CI/sequenceable/buffer_producer -I$CI/sequenceable/buffer_handle -I$CI/sequenceable/map_data
     -I$CI/sequenceable/include
     -I$S/graphic_graphic_surface/interfaces/inner_api/surface -I$S/graphic_graphic_surface/interfaces/inner_api/common
     -I$S/graphic_graphic_surface/interfaces/inner_api/utils -I$S/drivers_interface/display/graphic/common/v1_0
     -I$S/commonlibrary_c_utils/base/include -I$S/communication_ipc/interfaces/innerkits/ipc_core/include
     -I$S/communication_ipc/interfaces/innerkits/ipc_single/include -I$S/hiviewdfx_hilog/interfaces/native/innerkits/include"
CXX="$N/llvm/bin/clang++ --target=aarch64-linux-ohos --sysroot=$N/sysroot -O2 -Wall -Wextra -std=c++17
     -fno-exceptions -fno-rtti -nostdlib++ -include $COMMON/include/platform_cpp_config.h -fuse-ld=lld"
BASE="$L/libutils.z.so $L/libc++.so $L/libipc_single.z.so $L/libipc_common.z.so -Wl,--allow-shlib-undefined"
$CXX $INC -I$QCOM/camera/bridge $H/camera_host.cpp $L/libhdi.z.so $L/libhdi_base.z.so $O/link/libmetadata.z.so $BASE \
    -ldl -pthread -o $O/camera_host
ls -la $O/camera_host
